		});
		const tool = register(client);
		await handler(tool, "get-body-measurements")({ page: 2, page_size: 10 });
		await handler(tool, "get-body-measurement")({ date: "2025-01-01" });
		expect(client.getBodyMeasurements).toHaveBeenCalledWith({
			page: 2,
			pageSize: 10,
		});
